sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {

    if (isLoading) {
        return;
    }

    calculateEligibilityCount();


    function calculateEligibilityCount() {

        var branches = g_form.getValue('eligible_branches');
        var minimumCGPA = g_form.getValue('minimum_cgpa');
        var maxBacklogs = g_form.getValue('max_backlogs');
        var mandatorySkills = g_form.getValue('mandatory_skills');


        // =====================================================
        // WAIT UNTIL ALL 4 ELIGIBILITY FIELDS ARE FILLED
        // =====================================================

        if (!branches ||
            !minimumCGPA ||
            !maxBacklogs ||
            !mandatorySkills) {

            g_form.setValue('eligibility_count', '0');
            return;
        }


        // =====================================================
        // CALL SCRIPT INCLUDE
        // =====================================================

        var ga = new GlideAjax('PlacementDriveEligibility');

        ga.addParam(
            'sysparm_name',
            'calculateEligibility'
        );

        ga.addParam(
            'sysparm_branches',
            branches
        );

        ga.addParam(
            'sysparm_cgpa',
            minimumCGPA
        );

        ga.addParam(
            'sysparm_backlogs',
            maxBacklogs
        );

        ga.addParam(
            'sysparm_skills',
            mandatorySkills
        );


        // =====================================================
        // GET ELIGIBILITY COUNT
        // =====================================================

        ga.getXMLAnswer(function(answer) {

            if (answer === null ||
                answer === undefined ||
                answer === '') {

                g_form.setValue(
                    'eligibility_count',
                    '0'
                );

                return;
            }


            g_form.setValue(
                'eligibility_count',
                answer
            );

        });
    }
}
